<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paddock Lab</title>
<style>body{font:15px system-ui;background:#0d1117;color:#e6edf3;margin:0;padding:2rem}main{max-width:1100px;margin:auto}h1{margin-bottom:.25rem}.muted{color:#8b949e}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-top:2rem}.card{border:1px solid #30363d;border-radius:10px;padding:1rem;background:#161b22}.pass{border-color:#238636}.fail{border-color:#da3633}pre{white-space:pre-wrap;color:#8b949e}a{color:#58a6ff}</style></head><body><main><h1>Paddock Lab</h1><p class="muted">Laravel 13 · PHP 8.3–8.5 · live compatibility probes</p><div id="checks" class="grid"><div class="card">Running checks…</div></div></main>
<script src="/build/app.js" type="module"></script><script>const showReverb=result=>{const card=document.querySelector('[data-check="reverb"]');if(!card)return;card.classList.remove('pass','fail');card.classList.add(result.status);card.querySelector('pre').textContent=result.details};window.addEventListener('paddock-reverb-result',event=>showReverb(event.detail));fetch('/paddock/api/smoke').then(async r=>({data:await r.json(),header:r.headers.get('x-paddock-lab')})).then(({data,header})=>{if(!header){data.checks.http.status='fail';data.checks.http.details+='; X-Paddock-Lab header missing'}else data.checks.http.details+=`; nginx header ${header}`;document.querySelector('#checks').innerHTML=Object.entries(data.checks).map(([key,c])=>`<section data-check="${key}" class="card ${c.status}"><strong>${c.label}</strong><p>${c.status.toUpperCase()} · ${c.duration_ms} ms${c.version?' · '+c.version:''}</p><pre>${c.details}</pre>${c.url?`<a href="${c.url}">Open dashboard</a>`:''}</section>`).join('');if(window.paddockReverbResult)showReverb(window.paddockReverbResult)}).catch(e=>document.querySelector('#checks').innerHTML=`<section class="card fail">${e}</section>`)</script></body></html>
